public function get_coin_balance($login_id) {
    // SQL to calculate the amount for the ledger
    $sqlamt = "SELECT SUM(today_hisab) AS amount
                FROM tbl_final_hisab
                WHERE ledger_id = ?
                AND STR_TO_DATE(date, '%d-%m-%Y') BETWEEN DATE_FORMAT(CURDATE(), '%Y-%m-01')
                AND LAST_DAY(CURDATE())";
 
    // Execute the query for the amount
    $query = $this->db->query($sqlamt, array($login_id));
    $amount = 0; // Default amount

    // If there are results, sum the amounts
    if ($query->num_rows() > 0) {
        foreach ($query->result() as $row) {
            $amount += $row->amount; // Summing up all amounts
        }
    }

    // SQL to get the coin balance for the receiver
    $sql = "SELECT SUM(amount) AS coin_balance
            FROM coin_transactions
            WHERE receiver_id = ?";

    // Execute the query for the coin balance
    $coin_balance_query = $this->db->query($sql, array($login_id));
    $coin_balance = 0;

    // If there are results, get the coin balance
    if ($coin_balance_query->num_rows() > 0) {
        $coin_balance = $coin_balance_query->row()->coin_balance;
    }

    // Return the difference between the coin balance and the amount
    return $coin_balance - $amount;
}


public function updateStaffTransactionsapp($party_id,$amount, $shift_id, $date) 
{
    // Fetch all staff IDs associated with this master
    $this->db->select('id');
    $this->db->from('tbl_ledger');
    $this->db->where('id', $party_id);

    $staff_ids = $this->db->get()->result_array();

    if (empty($staff_ids)) {
        return false; // No staff found under this master
    }

    // Extract only the IDs into an array
    $staff_ids_array = array_column($staff_ids, 'id');
   // print_r($staff_ids_array);echo ' '.$shift_id; die;
   // print_r($staff_ids_array);
    // Update coin_transactions for the fetched staff members, for the given shift and date
    $this->db->where_in('sender_id', $staff_ids_array);
    $this->db->where('shift_id', $shift_id);
    $this->db->where('status', 1);
    $this->db->where('amount', $amount);
    $this->db->where('DATE(created_at)', $date); // Ensuring it's only for the given date
    $this->db->limit(1);
    $this->db->update('coin_transactions', ['status' => 0]);

    return $this->db->affected_rows() > 0; // Return true if any rows were updated
}

public function updateStaffTransactions($master_id, $shift_id, $date) 
{//echo $master_id.' '.$shift_id.' '.$date; die;
