// Allocate Coins
public function allocateCoins($sender_id, $receiver_id, $amount) { 
    if($sender_id != '1'){
        $sender_balance = $this->getUserBalance($sender_id);
    }
    else{
        $sender_balance = '9999999999999999999999';
    }
    

    if ($sender_balance >= $amount) {
        $type='allocation';
        if($sender_id != '1'){            
        // Deduct from sender
        $this->db->set('coin_balance', 'coin_balance - ' . (int)$amount, FALSE)
                 ->where('id', $sender_id)
                 ->update('tbl_ledger');
        }
        // Add to receiver
        $this->db->set('coin_balance', 'coin_balance + ' . (int)$amount, FALSE)
                 ->where('id', $receiver_id)
                 ->update('tbl_ledger');

        // Log transaction
        $this->db->insert('coin_transactions', [
            'sender_id' => $sender_id,
            'receiver_id' => $receiver_id,
            'amount' => $amount,
            'type' => 'allocation'
        ]);

        return true;
    }

    return false;
}
